const V3 = THREE.Vector3, Q = new URLSearchParams(location.search), FPS = 24, NF = 1392, DUR = NF / FPS, PI = Math.PI;
const qn = (k, d) => (Q.has(k) ? +Q.get(k) : d);
const clamp = (x, a = 0, b = 1) => Math.min(b, Math.max(a, x)), lerp = (a, b, k) => a + (b - a) * k;
const sstep = (a, b, x) => { const k = clamp((x - a) / (b - a)); return k * k * (3 - 2 * k); }, ease = (k) => { k = clamp(k); return k * k * (3 - 2 * k); };
const hash = (n) => { const s = Math.sin(n * 127.1 + 311.7) * 43758.5453; return s - Math.floor(s); };
const curve = (keys, t) => { if (t <= keys[0][0]) return keys[0][1]; for (let i = 1; i < keys.length; i++) if (t <= keys[i][0]) { const [t0, a] = keys[i - 1], [t1, b] = keys[i]; return lerp(a, b, ease((t - t0) / (t1 - t0))); } return keys[keys.length - 1][1]; };
const bump = (t, t0, up, hold, down) => t < t0 - up ? 0 : t < t0 ? ease((t - t0 + up) / up) : t < t0 + hold ? 1 : t < t0 + hold + down ? 1 - ease((t - t0 - hold) / down) : 0;
const v3 = (x = 0, y = 0, z = 0) => new V3(x, y, z);
// smooth 1D noise
const nz = (x) => { const i = Math.floor(x), f = x - i, u = f * f * (3 - 2 * f); return lerp(hash(i), hash(i + 1), u) * 2 - 1; };

const { renderer, post, canvas } = A.createAnimeRenderer({ width: 1920, height: 1080, samples: 4 });
document.body.appendChild(canvas);

